metrics.workdir_dsl:
workspace "Home Energy Management Platform" "C4 model of the home energy management platform" {

    model {

        homeowner = person "Homeowner" "A homeowner who manages their household's energy use and costs"

        energyManager = softwareSystem "Energy Manager" "Platform for managing a household's energy use and costs" {
            dashboard = container "Dashboard Web App" "Web app where homeowners see consumption and costs" "Web App" {
                dashboardRates = component "Rates Library" "Computes energy prices from tariffs and time of day" "Library"
            }
            scheduling = container "Scheduling Service" "Service that plans charging and heating" "Service" {
                schedulingRates = component "Rates Library" "Computes energy prices from tariffs and time of day" "Library"
            }
            database = container "Database" "Stores meter readings and schedules" "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "External provider of live meter readings" "External"

        homeowner -> dashboard "views consumption and costs" "HTTPS"
        scheduling -> smartMeterProvider "fetches live meter readings from" "HTTPS"
        scheduling -> database "stores meter readings and schedules in" "SQL"
        dashboard -> database "reads consumption and costs from" "SQL"
    }

    views {
        systemContext energyManager "SystemContext" {
            include *
            autoLayout
        }
        container energyManager "Containers" {
            include *
            autoLayout
        }
    }
}
